('int_full_body_3d', 'Intermediate Full Body', '{"schema_version":"1.0","program_id":"int_full_body_3d","name":"Intermediate Full Body","description":"3 days/week, RPE-based 6-week block. Full-body sessions for lifters who want the big three trained often but only have three days to train.","level":"intermediate","days_per_week":3,"weeks":6,"deload_week":6,"is_free":false,"sessions":[{"day":1,"name":"Full Body A","exercises":[{"lift":"squat","trackable":true,"prescriptions":[{"week":1,"sets":4,"reps":5,"rpe_target":7.5},{"week":2,"sets":4,"reps":5,"rpe_target":8},{"week":3,"sets":5,"reps":4,"rpe_target":8},{"week":4,"sets":5,"reps":3,"rpe_target":8.5},{"week":5,"sets":4,"reps":3,"rpe_target":9},{"week":6,"sets":2,"reps":5,"rpe_target":6,"deload":true}],"progression_note":"Add 2.5 kg / 5 lb whenever every set finishes at or below target RPE."},{"lift":"bench","trackable":true,"prescriptions":[{"week":1,"sets":4,"reps":6,"rpe_target":7.5},{"week":2,"sets":4,"reps":6,"rpe_target":8},{"week":3,"sets":4,"reps":5,"rpe_target":8},{"week":4,"sets":4,"reps":4,"rpe_target":8.5},{"week":5,"sets":4,"reps":4,"rpe_target":8.5},{"week":6,"sets":2,"reps":6,"rpe_target":6,"deload":true}],"progression_note":"Add 2.5 kg / 5 lb whenever every set finishes at or below target RPE."},{"lift":"barbell_row","trackable":false,"prescriptions":[{"week":1,"sets":3,"reps":8,"rpe_target":8},{"week":2,"sets":3,"reps":8,"rpe_target":8},{"week":3,"sets":4,"reps":8,"rpe_target":8},{"week":4,"sets":4,"reps":6,"rpe_target":8},{"week":5,"sets":4,"reps":6,"rpe_target":8.5},{"week":6,"sets":2,"reps":8,"rpe_target":6,"deload":true}],"progression_note":"Back volume to balance the pressing — keep strict form over load."}]},{"day":2,"name":"Full Body B","exercises":[{"lift":"deadlift","trackable":true,"prescriptions":[{"week":1,"sets":3,"reps":5,"rpe_target":7.5},{"week":2,"sets":3,"reps":5,"rpe_target":8},{"week":3,"sets":4,"reps":4,"rpe_target":8},{"week":4,"sets":4,"reps":3,"rpe_target":8.5},{"week":5,"set