('int_sbd_focus', 'SBD Focus', '{"schema_version":"1.0","program_id":"int_sbd_focus","name":"SBD Focus","description":"4 days/week, RPE-based 6-week block built around squat, bench, and deadlift as the main event every session — for lifters prioritizing the three competition lifts.","level":"intermediate","days_per_week":4,"weeks":6,"deload_week":6,"is_free":false,"sessions":[{"day":1,"name":"Squat Day","exercises":[{"lift":"squat","trackable":true,"prescriptions":[{"week":1,"sets":5,"reps":5,"rpe_target":7.5},{"week":2,"sets":5,"reps":4,"rpe_target":8},{"week":3,"sets":5,"reps":3,"rpe_target":8},{"week":4,"sets":5,"reps":3,"rpe_target":8.5},{"week":5,"sets":4,"reps":2,"rpe_target":9},{"week":6,"sets":2,"reps":5,"rpe_target":6,"deload":true}],"progression_note":"Main lift of the week. Add 2.5 kg / 5 lb whenever every set finishes at or below target RPE."},{"lift":"pause_squat","trackable":false,"prescriptions":[{"week":1,"sets":3,"reps":5,"rpe_target":7.5},{"week":2,"sets":3,"reps":5,"rpe_target":8},{"week":3,"sets":3,"reps":4,"rpe_target":8},{"week":4,"sets":3,"reps":4,"rpe_target":8},{"week":5,"sets":3,"reps":3,"rpe_target":8},{"week":6,"sets":2,"reps":5,"rpe_target":6,"deload":true}],"progression_note":"2-second pause at the bottom — builds out-of-the-hole strength. Lighter than the main squat."},{"lift":"leg_press","trackable":false,"prescriptions":[{"week":1,"sets":3,"reps":12,"rpe_target":8},{"week":2,"sets":3,"reps":12,"rpe_target":8},{"week":3,"sets":3,"reps":10,"rpe_target":8},{"week":4,"sets":3,"reps":10,"rpe_target":8},{"week":5,"sets":3,"reps":10,"rpe_target":8},{"week":6,"sets":2,"reps":12,"rpe_target":6,"deload":true}],"progression_note":"Quad volume to backfill the squat — add weight once RPE target is easily met."}]},{"day":2,"name":"Bench Day","exercises":[{"lift":"bench","trackable":true,"prescriptions":[{"week":1,"sets":5,"reps":5,"rpe_target":7.5},{"week":2,"sets":5,"reps":4,"rpe_target":8},{"week":3,"sets":5,"reps":3,"rpe_target":8},{"week":4,"s